// === Tab: mySketch ===
let n = 1200;
let dt = 0.02;
let frictionHalfLife = 0.040;
let rMax = 0.1;
let m = 6;
let mInt = Math.floor(m);
let forceFactor = 10;
let frictionFactor = Math.pow(0.5, dt / frictionHalfLife);
let matrix;

let particles = [];
let set = false;
let editingMatrix = false;
let thick = 3;

// Spatial grid
let gridSize = 10;
let grid = [];

function setup() {
  createCanvas(1000, 1000);
  colorMode(HSB, 360, 100, 100);
  background(0);

  initializeSystem();
}

function initializeSystem() {
  matrix = makeRandomMatrix();
  particles = [];

  // Rebuild grid
  grid = new Array(gridSize);
  for (let i = 0; i < gridSize; i++) {
    grid[i] = new Array(gridSize);
    for (let j = 0; j < gridSize; j++) {
      grid[i][j] = [];
    }
  }

  for (let i = 0; i < n; i++) {
    addRandomParticle();
  }
}

function draw() {
  updateGrid();
  updateParticles();

  // Fading trail
  noStroke();
  fill(0, 30);
  rect(0, 0, width, height);

  // Draw particles
  for (let p of particles) {
    p.display();
  }

  // UI
  if (set) {
    drawUI();
    if (editingMatrix) drawMatrixEditor();
  }
}

function updateGrid() {
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      grid[i][j] = [];
    }
  }
  for (let p of particles) {
    let x = constrain(Math.floor(p.position.x * gridSize), 0, gridSize - 1);
    let y = constrain(Math.floor(p.position.y * gridSize), 0, gridSize - 1);
    grid[x][y].push(p);
  }
}

function updateParticles() {
  for (let p1 of particles) {
    let totalForce = createVector();
    let xCell = Math.floor(p1.position.x * gridSize);
    let yCell = Math.floor(p1.position.y * gridSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        let nx = (xCell + i + gridSize) % gridSize;
        let ny = (yCell + j + gridSize) % gridSize;

        for (let p2 of grid[nx][ny]) {
          if (p1 === p2) continue;

          let rxy = p5.Vector.sub(p2.position, p1.position);

          if (Math.abs(rxy.x) > 0.5) rxy.x -= (rxy.x > 0) ? 1 : -1;
          if (Math.abs(rxy.y) > 0.5) rxy.y -= (rxy.y > 0) ? 1 : -1;

          let r = rxy.mag();
          if (r > 0 && r < rMax) {
            let f = force(r / rMax, matrix[p1.colorIndex][p2.colorIndex]);
            rxy.normalize().mult(f);
            totalForce.add(rxy);
          }
        }
      }
    }
    p1.applyForce(totalForce.mult(rMax * forceFactor));
  }

  for (let p of particles) {
    p.update();
  }
}

function drawUI() {
  fill(255);
  rect(0, 0, 200, 124, 30);
  fill(0);
  textSize(24);
  text("Particles: " + n, 20, 40);
  text("Thickness: " + thick, 20, 64);
  text("Colours: " + mInt, 20, 88);
  text("Force: " + forceFactor, 20, 112);
}

function drawMatrixEditor() {
  let cellSize = 30;
  let editorX = 200, editorY = 120;

  for (let i = 0; i < mInt; i++) {
    for (let j = 0; j < mInt; j++) {
      var x = editorX + i * cellSize;
      var y = editorY + j * cellSize;

      let val = matrix[i][j];
      if (val > 0) fill(0, 100, map(val, 0, 1, 50, 100));
      else fill(240, 100, map(Math.abs(val), 0, 1, 50, 100));

      stroke(0);
      rect(x, y, cellSize, cellSize);

      fill(255);
      textSize(12);
      textAlign(CENTER, CENTER);
      text(nf(val, 1, 2), x + cellSize/2, y + cellSize/2);
    }
  }

  fill(255);
  textSize(16);
  textAlign(LEFT);
  text("L-click: +0.05  R-click: -0.05", editorX, editorY - 10);
}

function mousePressed() {
  if (set && editingMatrix) {
    var cellSize = 30;
    var editorX = 200, editorY = 120;

    if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) >= editorX && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) >= editorY && 
        (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < editorX + mInt * cellSize && 
        (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < editorY + mInt * cellSize) {
      let i = Math.floor(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - editorX) / cellSize);
      let j = Math.floor(((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - editorY) / cellSize);

      if (mouseButton === LEFT) {
        matrix[i][j] = (matrix[i][j] + 0.05);
      } else if (mouseButton === RIGHT) {
        matrix[i][j] = (matrix[i][j] - 0.05);
      }

      // Clamp to [-1, 1]
      matrix[i][j] = constrain(matrix[i][j], -1, 1);
    }
  }
}

function addRandomParticle() {
  particles.push(new Particle(random(1), random(1), Math.floor(random(mInt))));
}

function makeRandomMatrix() {
  let mat = new Array(mInt);
  for (let i = 0; i < mInt; i++) {
    mat[i] = new Array(mInt);
    for (let j = 0; j < mInt; j++) {
      mat[i][j] = random(-1, 1);
    }
  }
  return mat;
}

function force(r, a) {
  let beta = 0.3;
  if (r < beta) return r / beta - 1;
  else if (r < 1) return a * (1 - Math.abs(2 * r - 1 - beta) / (1 - beta));
  else return 0;
}

function keyPressed() {
  if (key === 'r') {
    initializeSystem();
  }
  if (key === 's') set = !set;
  if (key === 'm') editingMatrix = !editingMatrix;
  if (keyCode === UP_ARROW) { 
    n += 60; 
    for (let i = 0; i < 60; i++) addRandomParticle(); 
  }
  if (keyCode === DOWN_ARROW && n > 60) { 
    n -= 60; 
    for (let i = 0; i < 60; i++) particles.shift(); 
  }
  if (keyCode === LEFT_ARROW && thick > 1) thick -= 1;
  if (keyCode === RIGHT_ARROW) thick += 1;
  if (key === 'a' && forceFactor > 0) forceFactor -= 0.5;
  if (key === 'd') forceFactor += 0.5;
  if (key === 'e') { 
    mInt++; 
    matrix = makeRandomMatrix(); 
    for (let p of particles) p.colorIndex = constrain(p.colorIndex, 0, mInt-1);
    initializeSystem();
  }
  if (key === 'q' && mInt > 1) { 
    mInt--; 
    matrix = makeRandomMatrix(); 
    for (let p of particles) p.colorIndex = constrain(p.colorIndex, 0, mInt-1);
    initializeSystem();
  }
}

class Particle {
  constructor(x, y, colorIndex) {
    this.position = createVector(x, y);
    this.velocity = createVector(0, 0);
    this.colorIndex = colorIndex;
  }

  applyForce(force) {
    this.velocity.mult(frictionFactor).add(p5.Vector.mult(force, dt));
  }

  update() {
    this.position.add(p5.Vector.mult(this.velocity, dt));
    if (this.position.x < 0) this.position.x = 1; 
    else if (this.position.x > 1) this.position.x = 0;
    if (this.position.y < 0) this.position.y = 1; 
    else if (this.position.y > 1) this.position.y = 0;
  }

  display() {
    fill(360.0 * this.colorIndex / mInt, 100, 100, 128);
    noStroke();
    ellipse(this.position.x * width, this.position.y * height, thick, thick);
  }
}

